class SwapArray {

    public static int[] swapArray(int[] newArray) {
        if (newArray.length == 0) {
            return newArray; // Return early if array is empty
        }
        int first = newArray[0];
        int last = newArray[newArray.length - 1];
        newArray[0] = last;
        newArray[newArray.length - 1] = first;
        return newArray;
    }
}

