class FindPlatform {

    public static int findPlatform(int[] arr, int[] dep, int n) {
        Arrays.sort(arr);
        Arrays.sort(dep);

        int plat_needed = 1; // Current platforms needed
        int result = 1; // Minimum platforms needed
        int i = 1; // Index for arrival array
        int j = 0; // Index for departure array

        while (i < n && j < n) {
            if (arr[i] <= dep[j]) {
                plat_needed++;
                i++;
            } else {
                plat_needed--;
                j++;
            }
            if (plat_needed > result) {
