class First {

    public static int first(int[] arr, int x, int n) {
        int low = 0;
        int high = n - 1;
        int result = -1; // To keep track of the index of the first occurrence
        while (low <= high) {
            int mid = (low + high) / 2;
            if (arr[mid] == x) {
                result = mid; // Store the index of x
                high = mid - 1; // Continue searching in the left half
            } else if (arr[mid] < x) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return result; // Return the first occurrence or -1 if not found
    }
}

