class Removals {

    public static int removals(int[] arr, int n, int k) {
        Arrays.sort(arr);  // Sorting to effectively find the appropriate range
        int left = 0;
        int right = 0;
        int maxRemovals = n;  // Maximum elements to be removed.

        while (right < n) {
            while (right < n && arr[right] - arr[left] <= k) {
                right++;
            }
            maxRemovals = Math.min(maxRemovals, n - (right - left));
            left++;
        }

        return maxRemovals;  // Return the minimum removals needed
    }
}

