class DivisibleByDigits {

    public static int[] divisibleByDigits(int startnum, int endnum) {
        int[] tempResult = new int[endnum - startnum + 1]; // Temporary array for results
        int resultSize = 0; // Counter for the valid results

        for (int i = startnum; i <= endnum; i++) {
            int temp = i;
            boolean isDivisible = true;

            while (temp > 0) {
                int digit = temp % 10;

                if (digit == 0 || i % digit != 0) {
                    isDivisible = false;
                    break;
                }
                temp /= 10;
            }

            if (isDivisible) {
                tempResult[resultSize++] = i; // Store valid result
            }
        }

        int[] result = new int[resultSize];
        System.arraycopy(tempResult, 0, result, 0, resultSize);
        return result;
    }
}

