class MulConsecutiveNums {

    public static int[] mulConsecutiveNums(int[] nums) {
        if (nums.length < 2) {
            return new int[0]; // Return an empty array if less than 2 elements
        }

        int[] ans = new int[nums.length - 1];

        for (int i = 1; i < nums.length; i++) {
