class MulEvenOdd {

    public static int mulEvenOdd(int[] array) {
        int first_even = -1;
        int first_odd = -1;

        for (int num : array) {
            if (first_even == -1 && num % 2 == 0) {
                first_even = num;
            }
            if (first_odd == -1 && num % 2 != 0) {
                first_odd = num;
            }
            if (first_even != -1 && first_odd != -1) {
                break;
            }
        }

        return (first_even * first_odd);
    }
}

