class ReArrangeArray {

    public static int[] reArrangeArray(int[] arr, int n) {
        int j = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] < 0) {
                int tmp = arr[j];
                arr[j] = arr[i];
                arr[i] = tmp;
                j++;
            }
        }

        int[] result = new int[Math.min(n, arr.length)];
        System.arraycopy(arr, 0, result, 0, result.length);
        return result;
    }
}

