class EquilibriumIndex {

    public static int equilibriumIndex(int[] arr) {
        int sum = 0;
        int leftSum = 0;

        for (int value : arr) {
            sum += value;
        }

        for (int i = 0; i < arr.length; i++) {
            sum -= arr[i]; // Right sum is total sum minus left sum (updated in each iteration)
            if (leftSum == sum) { // Check for equilibrium
                return i;
            }
            leftSum += arr[i]; // Update left sum
        }
        return -1; // If no equilibrium index is found
    }
}

